/* nairobi-noon - shadcn/ui theme (Tailwind v4).
   Drop into your global CSS after `@import "tailwindcss";`.
   Scoped to [data-theme="nairobi-noon"]; set it on <html> to activate.
   Values are the identity spec from identity.json. */

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-ok: var(--ok);
  --color-ok-soft: var(--ok-soft);
  --color-ok-foreground: var(--ok-fg);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-foreground: var(--warn-fg);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --font-display: "Lilita One", "Inter", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

[data-theme="nairobi-noon"] {
  --background: oklch(96% 0.02 80);
  --foreground: oklch(28% 0.02 60);
  --card: oklch(99% 0.01 80);
  --card-foreground: oklch(28% 0.02 60);
  --popover: oklch(99% 0.01 80);
  --popover-foreground: oklch(28% 0.02 60);
  --primary: oklch(52% 0.15 45);
  --primary-foreground: oklch(98% 0.008 45);
  --secondary: oklch(94% 0.04 45);
  --secondary-foreground: oklch(34% 0.08 45);
  --muted: oklch(93% 0.018 80);
  --muted-foreground: oklch(46% 0.03 60);
  --accent: oklch(94% 0.04 45);
  --accent-foreground: oklch(36% 0.09 45);
  --destructive: oklch(52% 0.17 30);
  --destructive-foreground: oklch(99% 0.005 30);
  --ok: oklch(46% 0.11 155);
  --ok-soft: oklch(95% 0.03 155);
  --ok-fg: oklch(38% 0.09 155);
  --warn: oklch(46% 0.1 70);
  --warn-soft: oklch(96% 0.035 85);
  --warn-fg: oklch(38% 0.07 65);
  --border: oklch(89% 0.025 80);
  --input: oklch(89% 0.025 80);
  --ring: oklch(52% 0.15 45);
  --radius: 0.625rem;
  --font-display: "Lilita One", "Inter", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  --shadow-identity: 0 1px 2px oklch(28% 0.02 60 / 0.08), 0 10px 28px oklch(28% 0.02 60 / 0.07);
  --identity-gradient-to: oklch(38% 0.12 40);
  color-scheme: light;
}

/* Identity signatures: Lilita One display keeps its rounded personality. */
[data-theme="nairobi-noon"] h1,
[data-theme="nairobi-noon"] h2,
[data-theme="nairobi-noon"] h3,
[data-theme="nairobi-noon"] .font-display {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: 0.01em;
}
[data-theme="nairobi-noon"] .tabular {
  font-variant-numeric: tabular-nums;
}
[data-theme="nairobi-noon"] body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}
@media (prefers-reduced-motion: reduce) {
  [data-theme="nairobi-noon"] *, [data-theme="nairobi-noon"] *::before, [data-theme="nairobi-noon"] *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}


/* ---- overrides ---- */
/* nairobi-noon overrides - warm, relaxed treatments on top of stock shadcn.
   Layer AFTER shadcn styles. Each rule is a deliberate identity decision. */

[data-identity="nairobi-noon"] [data-slot="button"][data-variant="default"] {
  font-weight: 600;
  box-shadow: 0 2px 8px oklch(52% 0.15 45 / 0.28);
}
[data-identity="nairobi-noon"] [data-slot="button"]:hover {
  transform: translateY(-1px);
}
[data-identity="nairobi-noon"] [data-slot="button"]:active {
  transform: translateY(0);
}
[data-identity="nairobi-noon"] [data-slot="button"] {
  transition: transform 200ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 200ms cubic-bezier(0.22, 0.61, 0.36, 1);
  border-radius: 10px;
}

/* Cards: warm surfaces, gentle noon shadow. */
[data-identity="nairobi-noon"] [data-slot="card"] {
  border-radius: 12px;
  box-shadow: 0 1px 2px oklch(28% 0.02 60 / 0.08), 0 10px 28px oklch(28% 0.02 60 / 0.07);
  transition: transform 220ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 220ms cubic-bezier(0.22, 0.61, 0.36, 1);
}
[data-identity="nairobi-noon"] a[data-slot="card"]:hover,
[data-identity="nairobi-noon"] .hover-lift:hover {
  transform: translateY(-3px);
  box-shadow: 0 2px 4px oklch(28% 0.02 60 / 0.08), 0 14px 34px oklch(52% 0.15 45 / 0.14);
}

/* Focus: warm halo. */
[data-identity="nairobi-noon"] :focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px oklch(94% 0.04 45), 0 0 0 5px oklch(52% 0.15 45 / 0.5);
  border-radius: 8px;
}

/* Tables: airy, warm header band, tabular numbers. */
[data-identity="nairobi-noon"] table {
  font-variant-numeric: tabular-nums;
  border-collapse: separate;
  border-spacing: 0;
}
[data-identity="nairobi-noon"] th {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(46% 0.03 60);
}

/* Badges: uppercase tracking. */
[data-identity="nairobi-noon"] [data-slot="badge"] {
  letter-spacing: 0.05em;
  font-weight: 700;
}

/* Inputs: soft warm focus. */
[data-identity="nairobi-noon"] input,
[data-identity="nairobi-noon"] textarea,
[data-identity="nairobi-noon"] select {
  transition: border-color 180ms ease, box-shadow 180ms ease;
}

import type { ReactNode } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"

export function Article({
  eyebrow,
  title,
  meta,
  children,
}: {
  eyebrow: string
  title: string
  meta: string
  children: ReactNode
}) {
  return (
    <article className="mx-auto max-w-[760px] px-6 py-14">
      <span className="text-[11.5px] font-extrabold uppercase tracking-[0.16em] text-primary">
        {eyebrow}
      </span>
      <h1 className="mt-3 font-display text-[28px] leading-[1.12]">
        {title}
      </h1>
      <p className="mt-3 text-[13px] text-muted-foreground">{meta}</p>
      <div className="mt-8 flex flex-col gap-6 text-[16px] leading-[1.6] [&_blockquote]:border-l-4 [&_blockquote]:border-primary/40 [&_blockquote]:pl-4 [&_blockquote]:italic [&_h2]:mt-10 [&_h2]:font-display [&_h2]:text-[21px] [&_li]:mt-2 [&_ul]:ml-5 [&_ul]:list-disc">
        {children}
      </div>
    </article>
  )
}

export function Callout({ tone = "info", children }: { tone?: "info" | "warn"; children: ReactNode }) {
  return (
    <Card className={`border-none py-0 ${tone === "warn" ? "bg-warn-soft" : "bg-accent"}`}>
      <CardContent className={`p-4 text-[13px] leading-relaxed ${tone === "warn" ? "text-warn-foreground" : ""}`}>
        {children}
      </CardContent>
    </Card>
  )
}

export function Kpi({ value, label }: { value: string; label: string }) {
  return (
    <Card className="py-4">
      <CardContent className="px-4">
        <b className="font-display text-[26px] tabular-nums">{value}</b>
        <span className="mt-0.5 block text-[11.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
          {label}
        </span>
      </CardContent>
    </Card>
  )
}

import type { ReactNode } from "react"
import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"

export function DashboardShell({
  title,
  nav,
  actions,
  stats,
  children,
}: {
  title: string
  nav: { label: string; active?: boolean; count?: number }[]
  actions?: ReactNode
  stats: { value: string; label: string }[]
  children: ReactNode
}) {
  return (
    <div className="min-h-screen">
      <header className="sticky top-0 z-40 border-b border-border/80 bg-card/85 backdrop-blur-md">
        <div className="mx-auto flex h-[60px] max-w-[1120px] items-center gap-4 px-6 sm:gap-6">
          <span className="min-w-0 truncate font-display text-[19px]">
            {title}
          </span>
          <nav className="ml-auto flex shrink-0 items-center gap-4 sm:gap-6">
            {nav.map((n) => (
              <a
                key={n.label}
                href="#"
                className={`text-sm font-medium transition-colors ${
                  n.active ? "font-semibold text-foreground" : "text-muted-foreground hover:text-primary"
                }`}
              >
                {n.label}
                {n.count ? ` (${n.count})` : ""}
              </a>
            ))}
          </nav>
          {actions && <div className="flex shrink-0 items-center gap-3">{actions}</div>}
        </div>
      </header>

      <main className="mx-auto max-w-[1120px] px-6 py-10">
        <div className="mb-8 grid grid-cols-2 gap-4 lg:grid-cols-4">
          {stats.map((s) => (
            <Card key={s.label} className="py-4">
              <CardContent className="px-4">
                <b className="font-display text-[26px] tabular-nums">{s.value}</b>
                <span className="mt-0.5 block text-[11.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
                  {s.label}
                </span>
              </CardContent>
            </Card>
          ))}
        </div>
        {children}
      </main>
    </div>
  )
}

export function StatBadge({ label, tone = "muted" }: { label: string; tone?: "muted" | "ok" | "warn" | "danger" }) {
  const tones = {
    muted: "bg-secondary text-secondary-foreground",
    ok: "bg-ok-soft text-ok-foreground",
    warn: "bg-warn-soft text-warn-foreground",
    danger: "bg-destructive/10 text-destructive",
  }
  return <Badge className={`rounded-md px-2 py-0.5 text-[11px] uppercase ${tones[tone]}`}>{label}</Badge>
}
